package org.sleepwell.app;
import android.content.*;import android.net.Uri;import android.os.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Retained explicit SAF work. No file selection or import review grants runtime authority. */
final class SettingsProfileJob {
 enum Phase{IDLE,PREPARING,EXPORT_READY,CHOOSING,READING,REVIEW,WRITING,APPLYING,RECOVERING,CLOSING,BLOCKED,DONE,ERROR}
 enum Kind{EXPORT,IMPORT}
 static final class State{final Phase phase;final String message;final SettingsProfile profile;final boolean busy;State(Phase p,String m,SettingsProfile profile,boolean busy){phase=p;message=m;this.profile=profile;this.busy=busy;}}
 private static SettingsProfileJob singleton;static synchronized SettingsProfileJob get(Context context){if(singleton==null)singleton=new SettingsProfileJob(context.getApplicationContext());return singleton;}
 final String id=UUID.randomUUID().toString();private final Context app;private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private final AtomicBoolean occupied=new AtomicBoolean(),cancelled=new AtomicBoolean();private volatile State state=new State(Phase.IDLE,"",null,false);private volatile Transport transport;private volatile byte[] prepared;private volatile SettingsProfile incoming;private String fingerprint="",ticket="";private long admission,generation;private Kind choosing;
 private SettingsProfileJob(Context app){this.app=app;}State state(){return state;}boolean recovery(){return SettingsProfilePersistence.interrupted(app);}
 private interface Work{State run()throws Exception;}
 private boolean begin(Phase phase,Work work){if(!occupied.compareAndSet(false,true))return false;cancelled.set(false);long mine=++generation;state=new State(phase,"",state.profile,true);if(phase!=Phase.APPLYING&&phase!=Phase.RECOVERING)main.postDelayed(()->{if(generation==mine&&occupied.get()&&state.phase!=Phase.BLOCKED)cancel();},45000);try{worker.execute(()->{State result;try{result=work.run();if(cancelled.get())throw new InterruptedIOException("Document operation cancelled. A selected export may be empty or partial.");}catch(Exception failure){result=new State(incoming!=null?Phase.REVIEW:Phase.ERROR,SettingsProfilePersistence.message(failure),incoming,false);}Transport owner=transport;if(owner!=null)try{owner.finish();}catch(IOException close){state=new State(Phase.BLOCKED,"Document cleanup is unconfirmed. Retry closing it before another operation.",result.profile,true);return;}transport=null;state=result;occupied.set(false);});return true;}catch(RuntimeException unavailable){state=new State(Phase.ERROR,"Settings worker could not start.",state.profile,false);occupied.set(false);return false;}}
 boolean prepare(boolean[] selection){if(recovery()||state.phase==Phase.CHOOSING)return false;boolean[] include=selection.clone();return begin(Phase.PREPARING,()->{active();SettingsProfile profile=SettingsProfile.capture(app,include);byte[] bytes=profile.encode().getBytes(StandardCharsets.UTF_8);if(bytes.length>SettingsProfile.LIMIT)throw new IOException("Settings profiles must fit within 64 KiB.");active();prepared=bytes;incoming=null;return new State(Phase.EXPORT_READY,"Review this frozen settings copy before choosing its destination.",profile,false);});}
 synchronized String choose(Kind kind){if(occupied.get()||recovery()||state.phase==Phase.CHOOSING||kind==Kind.EXPORT&&(prepared==null||state.phase!=Phase.EXPORT_READY))return "";choosing=kind;ticket=UUID.randomUUID().toString();if(kind==Kind.IMPORT){incoming=null;prepared=null;}state=new State(Phase.CHOOSING,"Choose a settings document.",state.profile,false);return ticket;}
 synchronized void cancelledChoice(String expected){if(!ticket.equals(expected)||state.phase!=Phase.CHOOSING)return;ticket="";state=new State(choosing==Kind.EXPORT&&prepared!=null?Phase.EXPORT_READY:Phase.IDLE,"Document selection cancelled. No settings changed.",choosing==Kind.EXPORT?state.profile:null,false);}
 synchronized boolean document(String expected,Uri uri){if(!ticket.equals(expected)||state.phase!=Phase.CHOOSING||uri==null||!"content".equals(uri.getScheme())||uri.getAuthority()==null)return false;ticket="";String chosen=uri.toString();if(choosing==Kind.EXPORT){byte[] copy=prepared;if(copy==null)return false;return begin(Phase.WRITING,()->{Transport io=new Transport(app,cancelled);transport=io;active();try(OutputStream output=io.output(chosen)){for(int at=0;at<copy.length;at+=4096){active();output.write(copy,at,Math.min(4096,copy.length-at));}active();output.flush();}prepared=null;return new State(Phase.DONE,"Settings profile exported. Records, alarms and excluded private settings were not included.",null,false);});}return begin(Phase.READING,()->{Transport io=new Transport(app,cancelled);transport=io;String text;try(InputStream input=io.input(chosen)){text=SettingsProfileJson.read(input,()->!cancelled.get());}active();SettingsProfile profile=SettingsProfile.decode(text);long current=BackupRuntime.generation();SettingsProfilePersistence.idle(app,current,null);String identity=SettingsProfilePersistence.fingerprint(app);active();admission=current;fingerprint=identity;incoming=profile;return new State(Phase.REVIEW,"Review every included category. Nothing has been applied.",profile,false);});}
 boolean refresh(){SettingsProfile profile=incoming;if(profile==null||recovery())return false;return begin(Phase.READING,()->{long current=BackupRuntime.generation();SettingsProfilePersistence.idle(app,current,null);fingerprint=SettingsProfilePersistence.fingerprint(app);admission=current;return new State(Phase.REVIEW,"Review refreshed against current settings. Confirm Apply again.",profile,false);});}
 boolean apply(){State reviewed=state;if(reviewed.phase!=Phase.REVIEW||reviewed.profile==null||recovery())return false;String expected=fingerprint;long current=admission;return begin(Phase.APPLYING,()->{String result=SettingsProfilePersistence.apply(app,reviewed.profile,expected,current);incoming=null;prepared=null;return new State(Phase.DONE,result,null,false);});}
 boolean recover(){if(!recovery())return false;return begin(Phase.RECOVERING,()->{String result=SettingsProfilePersistence.rollback(app,BackupRuntime.generation());incoming=null;prepared=null;return new State(Phase.DONE,result,null,false);});}
 void discard(){if(occupied.get()||state.phase==Phase.CHOOSING)return;incoming=null;prepared=null;state=new State(Phase.IDLE,"Review discarded. Saved settings were kept.",null,false);}
 void cancel(){if(!occupied.get()||state.phase==Phase.APPLYING||state.phase==Phase.RECOVERING||state.phase==Phase.BLOCKED)return;cancelled.set(true);state=new State(Phase.CLOSING,"Stopping document work…",state.profile,true);Transport io=transport;if(io!=null)io.cancel();}
 void retryClose(){if(state.phase!=Phase.BLOCKED||transport==null)return;Transport retained=transport;state=new State(Phase.CLOSING,"Retrying document cleanup…",state.profile,true);worker.execute(()->{try{retained.finish();transport=null;occupied.set(false);state=new State(Phase.ERROR,"Document closed. Choose it again before continuing.",null,false);}catch(IOException failure){state=new State(Phase.BLOCKED,"Document remains open. Retry cleanup later.",state.profile,true);}});}
 private void active()throws IOException{BackupIo.active(()->!cancelled.get());}
 private static final class Transport{private static final Executor CLOSE=Executors.newSingleThreadExecutor(r->{Thread thread=new Thread(r,"settings-profile-document-close");thread.setDaemon(true);return thread;});final ContentResolver resolver;final AtomicBoolean cancelled;final AtomicReference<CancellationSignal> signal=new AtomicReference<>();final AtomicReference<ParcelFileDescriptor> descriptor=new AtomicReference<>();Transport(Context context,AtomicBoolean cancelled){resolver=context.getContentResolver();this.cancelled=cancelled;}ParcelFileDescriptor open(String uri,String mode)throws IOException{CancellationSignal pending=new CancellationSignal();signal.set(pending);if(cancelled.get())throw new InterruptedIOException("Document operation cancelled.");ParcelFileDescriptor file=resolver.openFileDescriptor(Uri.parse(uri),mode,pending);if(file==null)throw new IOException("The settings document is unavailable.");descriptor.set(file);if(cancelled.get()){finish();throw new InterruptedIOException("Document operation cancelled.");}return file;}InputStream input(String uri)throws IOException{return new ParcelFileDescriptor.AutoCloseInputStream(open(uri,"r"));}OutputStream output(String uri)throws IOException{return new ParcelFileDescriptor.AutoCloseOutputStream(open(uri,"wt"));}void finish()throws IOException{ParcelFileDescriptor file=descriptor.get();if(file!=null){file.close();descriptor.compareAndSet(file,null);}signal.set(null);}void cancel(){CancellationSignal pending=signal.get();CLOSE.execute(()->{try{if(pending!=null)pending.cancel();}finally{try{finish();}catch(IOException ignored){}}});}}
}
